{"file_path":"src/normalizer.js","content":"import { parseUri, parseAuthority, reconstructUri } from './parser.js';

/**
 * Check if a character is hexadecimal
 */
function isHexDigit(ch) {
  return /[0-9A-Fa-f]/.test(ch);
}

/**
 * Check if a character code is unreserved
 */
function isUnreserved(code) {
  // A-Z: 65-90, a-z: 97-122, 0-9: 48-57, -: 45, .: 46, _: 95, ~: 126
  return (code >= 65 && code <= 90) || // A-Z
         (code >= 97 && code <= 122) || // a-z
         (code >= 48 && code <= 57) || // 0-9
         code === 45 || // -
         code === 46 || // .
         code === 95 || // _
         code === 126; // ~
}

/**
 * Normalize percent-encodings in a component.
 * Returns { result, error } where error is null on success or
 * contains error message on failure.
 */
function normalizePercentEncoding(component, componentName) {
  if (!component) return { result: component, error: null };

  let result = '';
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return { result: null, error: componentName };
      }
      const hex1 = component[i + 1];
      const hex2 = component[i + 2];
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) {
        return { result: null, error: componentName };
      }
      const code = parseInt(hex1 + hex2, 16);
      if (isUnreserved(code)) {
        result += String.fromCharCode(code);
      } else {
        result += '%' + hex1.toUpperCase() + hex2.toUpperCase();
      }
      i += 2;
    } else {
      result += component[i];
    }
  }
  return { result, error: null };
}

/**
 * Normalize a URI reference
 * Returns { result, error } where error is null on success or
 * contains { message, lineNumber } on failure
 */
export function normalizeUri(uriRef, lineNumber = 1) {
  const parsed = parseUri(uriRef);

  // Lowercase scheme
  if (parsed.scheme !== undefined) {
    parsed.scheme = parsed.scheme.toLowerCase();
  }

  // Normalize authority components
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority);

    // Normalize userinfo
    if (auth.userinfo !== undefined) {
      const { result, error } = normalizePercentEncoding(auth.userinfo, 'userinfo');
      if (error) {
        return { result: null, error: { message: `error: line ${lineNumber}: the ${error} has a truncated percent-encoding`, lineNumber } };
      }
      auth.userinfo = result;
    }

    // Normalize host
    if (auth.host !== undefined) {
      const { result, error } = normalizePercentEncoding(auth.host, 'host');
      if (error) {
        return { result: null, error: { message: `error: line ${lineNumber}: the ${error} has a truncated percent-encoding`, lineNumber } };
      }
      auth.host = result.toLowerCase();
    }

    // Port stays as is (but may be dropped if default)
    // Reconstruct authority
    let newAuth = '';
    if (auth.userinfo !== undefined) {
      newAuth += auth.userinfo + '@';
    }
    newAuth += auth.host;
    if (auth.port !== undefined && auth.port !== '') {
      // Check if port is default for the scheme
      const defaultPorts = {
        'http': '80',
        'ws': '80',
        'https': '443',
        'wss': '443',
        'ftp': '21'
      };
      const scheme = parsed.scheme || '';
      const defaultPort = defaultPorts[scheme];

      // Only drop if it's exactly the default port (no leading zeros)
      if (!(defaultPort && auth.port === defaultPort)) {
        newAuth += ':' + auth.port;
      }
    }
    parsed.authority = newAuth;
  }

  // Normalize path
  if (parsed.path) {
    const { result, error } = normalizePercentEncoding(parsed.path, 'path');
    if (error) {
      return { result: null, error: { message: `error: line ${lineNumber}: the ${error} has a truncated percent-encoding`, lineNumber } };
    }
    parsed.path = removeDotSegments(result);
  }

  // Normalize query
  if (parsed.query !== undefined) {
    const { result, error } = normalizePercentEncoding(parsed.query, 'query');
    if (error) {
      return { result: null, error: { message: `error: line ${lineNumber}: the ${error} has a truncated percent-encoding`, lineNumber } };
    }
    parsed.query = result;
  }

  // Normalize fragment
  if (parsed.fragment !== undefined) {
    const { result, error } = normalizePercentEncoding(parsed.fragment, 'fragment');
    if (error) {
      return { result: null, error: { message: `error: line ${lineNumber}: the ${error} has a truncated percent-encoding`, lineNumber } };
    }
    parsed.fragment = result;
  }

  // If authority is present and path is empty, make path /
  if (parsed.authority !== undefined && parsed.path === '') {
    parsed.path = '/';
  }

  return { result: reconstructUri(parsed), error: null };
}

/**
 * Remove dot segments from a path according to RFC 3986 section 5.2.4
 */
function removeDotSegments(path) {
  const input = path;
  const output = [];

  let i = 0;
  while (i < input.length) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (input.startsWith('../', i)) {
      i += 3;
    } else if (input.startsWith('./', i)) {
      i += 2;
    }
    // B: If the input buffer begins with a prefix of "/./" or "/.", where "." is a complete path segment
    else if (input.startsWith('/./,', i) || (input.startsWith('/.', i) && (i + 2 === input.length))) {
      i += 2;
      // We'll add the / at the next iteration or at the end
    } else if (input.startsWith('/./', i)) {
      i += 3;
    }
    // C: If the input buffer begins with a prefix of "/../" or "/..", where ".." is a complete path segment
    else if (input.startsWith('/../', i) || (input.startsWith('/..', i) && (i + 3 === input.length))) {
      i += 3;
      if (output.length > 0) {
        output.pop();
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if ((input === '.' || input === '..') && i === 0) {
      i = input.length;
    }
    // E: move the first path segment (including initial "/" if any) to the output buffer
    else {
      let segEnd = i + 1;
      while (segEnd < input.length && input[segEnd] !== '/') {
        segEnd++;
      }
      output.push(input.slice(i, segEnd));
      i = segEnd;
    }
  }

  return output.join('');
}
"}

