{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { normalizeUri } from './normalizer.js';
import { resolveUri } from './resolver.js';
import { stdin, stdout, stderr } from 'process';

const args = process.argv.slice(2);

// Check arguments
if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  stderr.write('error: usage: cli.js normalize|resolve\n');
  process.exit(2);
}

const mode = args[0];

// Read all input
let input = '';
stdin.setEncoding('utf8');

stdin.on('data', chunk => {
  input += chunk;
});

stdin.on('end', () => {
  // Split on newlines and drop empty tail
  const lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  let hasError = false;

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1;
    const line = lines[i];

    let result;

    if (mode === 'normalize') {
      result = normalizeUri(line, lineNumber);
    } else {
      // resolve mode
      const spaceIdx = line.indexOf(' ');
      if (spaceIdx === -1) {
        stderr.write(`error: line ${lineNumber}: expected a base and a reference\n`);
        process.exit(2);
      }

      const base = line.slice(0, spaceIdx);
      const reference = line.slice(spaceIdx + 1);

      result = resolveUri(base, reference, lineNumber);
    }

    if (result.error) {
      stderr.write(result.error.message + '\n');
      process.exit(2);
    }

    stdout.write(result.result + '\n');
  }

  process.exit(0);
});
"}

