{"file_path":"src/normalizer.js","content":"import { parseUri, parseAuthority, reconstructUri } from './parser.js';

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21'
};

function asciiLower(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += (c >= 65 && c <= 90) ? String.fromCharCode(c + 32) : s[i];
  }
  return out;
}

function isHexDigit(ch) {
  const c = ch.charCodeAt(0);
  return (c >= 48 && c <= 57) || (c >= 65 && c <= 70) || (c >= 97 && c <= 102);
}

function isUnreserved(code) {
  return (code >= 65 && code <= 90) ||
         (code >= 97 && code <= 122) ||
         (code >= 48 && code <= 57) ||
         code === 45 || code === 46 || code === 95 || code === 126;
}

/** Returns a string, or null when a percent-encoding is truncated. */
function normalizePercentEncoding(component) {
  if (component === undefined || component === null) return component;
  if (component.indexOf('%') === -1) return component;

  let result = '';
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) return null;
      const hex1 = component[i + 1];
      const hex2 = component[i + 2];
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) return null;
      const code = parseInt(hex1 + hex2, 16);
      if (isUnreserved(code)) {
        result += String.fromCharCode(code);
      } else {
        result += '%' + hex1.toUpperCase() + hex2.toUpperCase();
      }
      i += 2;
    } else {
      result += component[i];
    }
  }
  return result;
}

/** RFC 3986 section 5.2.4 */
export function removeDotSegments(path) {
  let input = path;
  let output = '';

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3);
    } else if (input.startsWith('./')) {
      input = input.slice(2);
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3);
    } else if (input === '/.') {
      input = '/';
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4);
      const cut = output.lastIndexOf('/');
      output = cut === -1 ? '' : output.slice(0, cut);
    } else if (input === '/..') {
      input = '/';
      const cut = output.lastIndexOf('/');
      output = cut === -1 ? '' : output.slice(0, cut);
    } else if (input === '.' || input === '..') {
      input = '';
    } else {
      let end = input[0] === '/' ? 1 : 0;
      while (end < input.length && input[end] !== '/') end++;
      output += input.slice(0, end);
      input = input.slice(end);
    }
  }

  return output;
}

function truncationError(component, lineNumber) {
  return {
    result: null,
    error: {
      message: `error: line ${lineNumber}: the ${component} has a truncated percent-encoding`,
      lineNumber
    }
  };
}

/**
 * Normalize a parsed URI reference in place and return { result, error }.
 */
export function normalizeParsed(parsed, lineNumber = 1) {
  // 1. Lowercase the scheme (ASCII only).
  if (parsed.scheme !== undefined) {
    parsed.scheme = asciiLower(parsed.scheme);
  }

  const auth = parsed.authority !== undefined
    ? parseAuthority(parsed.authority)
    : null;

  // 2. Percent-encoding normalization, checked in order:
  //    path, userinfo, host, query, fragment.
  const path = normalizePercentEncoding(parsed.path);
  if (path === null) return truncationError('path', lineNumber);

  let userinfo, host;
  if (auth) {
    if (auth.userinfo !== undefined) {
      userinfo = normalizePercentEncoding(auth.userinfo);
      if (userinfo === null) return truncationError('userinfo', lineNumber);
    }
    host = normalizePercentEncoding(auth.host);
    if (host === null) return truncationError('host', lineNumber);
  }

  let query;
  if (parsed.query !== undefined) {
    query = normalizePercentEncoding(parsed.query);
    if (query === null) return truncationError('query', lineNumber);
  }

  let fragment;
  if (parsed.fragment !== undefined) {
    fragment = normalizePercentEncoding(parsed.fragment);
    if (fragment === null) return truncationError('fragment', lineNumber);
  }

  parsed.path = path;
  if (parsed.query !== undefined) parsed.query = query;
  if (parsed.fragment !== undefined) parsed.fragment = fragment;

  if (auth) {
    // 3. Lowercase the host (ASCII only); leave the userinfo alone.
    host = asciiLower(host);

    // 4. Drop an empty port or the scheme's default port.
    let port = auth.port;
    if (port !== undefined) {
      const dflt = DEFAULT_PORTS[parsed.scheme === undefined ? '' : parsed.scheme];
      if (port === '' || (dflt !== undefined && port === dflt)) {
        port = undefined;
      }
    }

    let rebuilt = '';
    if (userinfo !== undefined) rebuilt += userinfo + '@';
    rebuilt += host;
    if (port !== undefined) rebuilt += ':' + port;
    parsed.authority = rebuilt;
  }

  // 5. Remove dot segments from the path.
  parsed.path = removeDotSegments(parsed.path);

  // 6. An authority with an empty path gets "/".
  if (parsed.authority !== undefined && parsed.path === '') {
    parsed.path = '/';
  }

  return { result: reconstructUri(parsed), error: null };
}

export function normalizeUri(uriRef, lineNumber = 1) {
  return normalizeParsed(parseUri(uriRef), lineNumber);
}
"}

