import { normalizeUri } from './normalizer.js';
import { resolveUri } from './resolver.js';

function fail(message) {
  process.stderr.write(message + '\n');
  process.exitCode = 2;
}

function main(mode, input) {
  const lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  const out = [];

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1;
    const line = lines[i];
    let result;

    if (mode === 'normalize') {
      result = normalizeUri(line, lineNumber);
    } else {
      const spaceIdx = line.indexOf(' ');
      if (spaceIdx === -1) {
        fail(`error: line ${lineNumber}: expected a base and a reference`);
        return;
      }
      result = resolveUri(line.slice(0, spaceIdx), line.slice(spaceIdx + 1), lineNumber);
    }

    if (result.error) {
      fail(result.error.message);
      return;
    }

    out.push(result.result + '\n');
  }

  if (out.length > 0) process.stdout.write(out.join(''));
}

const args = process.argv.slice(2);

if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n');
  process.exit(2);
}

const mode = args[0];
const chunks = [];

process.stdin.on('data', chunk => chunks.push(chunk));
process.stdin.on('end', () => {
  main(mode, Buffer.concat(chunks).toString('utf8'));
});

