let port = undefined;
let host = hostPort;

// Find the last ] (for IPv6)
const lastBracket = hostPort.lastIndexOf(']');
const colonIdx = hostPort.indexOf(':');

if (colonIdx !== -1) {
  // If there's a ] and the : is after it, this : is for the port
  if (lastBracket !== -1 && colonIdx > lastBracket) {
    port = hostPort.slice(colonIdx + 1);
    host = hostPort.slice(0, colonIdx);
  } else if (lastBracket === -1) {
    // No IPv6, so first : is the port separator
    port = hostPort.slice(colonIdx + 1);
    host = hostPort.slice(0, colonIdx);
  }
}

return { userinfo, host, port };

